// Hatchfield asset manifest (grok/assets). Generated by the assets worker.
// All paths are served from public/ (Vite), so "/assets/x" maps to public/assets/x.
// Assets are SVG: tiny, crisp, and rasterise to any power-of-two size via loadAssetTexture.

export interface TextureAsset {
  albedo: string;
  size: number;
  roughness: number;
  metalness: number;
  repeatMeters: number;
}

export interface Livery {
  name: string;
  code: string;
  tailDecal: string;
  fuselage: string;
  stripePrimary: string;
  stripeAccent: string;
  engine: string;
  motif: string;
}

